def largestEven(s):
    # Find the position of the last '2'; the number must end with it
    last = -1
    for i in range(len(s)):
        if s[i] == '2':
            last = i
    # No '2' means no even number is possible
    if last == -1:
        return ""
    # Keep everything up to and including the last '2' (longest possible, so largest)
    return s[:last + 1]
